import numpy as np
from collections import deque
f=np.load('source_pixels.npz')['rgb']
mask=(f[:,:,:,1]>120)&(f[:,:,:,0]>100)&(f[:,:,:,2]<100)&(f[:,:,:,1]-f[:,:,:,2]>60)
def comps(m, minsize=2):
 h,w=m.shape; seen=np.zeros_like(m,bool); out=[]
 for y,x in zip(*np.where(m & ~seen)):
  q=[(y,x)]; seen[y,x]=1; pts=[]
  while q:
   cy,cx=q.pop(); pts.append((cy,cx))
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     if dy==0 and dx==0: continue
     ny,nx=cy+dy,cx+dx
     if 0<=ny<h and 0<=nx<w and m[ny,nx] and not seen[ny,nx]:
      seen[ny,nx]=1;q.append((ny,nx))
  if len(pts)>=minsize:
   a=np.array(pts); out.append((len(pts),a[:,1].min(),a[:,0].min(),a[:,1].max(),a[:,0].max(),a[:,1].mean(),a[:,0].mean()))
 return sorted(out,reverse=True)
for i in [0,5,10,15,18,19,20,21,22,23,24,30,40,60,95]:
 print('\\nframe',i)
 for c in comps(mask[i],2)[:10]: print(tuple(round(v,1) if isinstance(v,float) else v for v in c))
